-- RLS for kon-ingest after the English rename: functions, triggers and policies come back with the new names.
--
-- The previous file dropped the old ones; between both files the tables stay closed, not open.

-- Policies, with the new names and the core's English helpers.
DROP POLICY IF EXISTS ingest_chunks_delete ON ingest_chunks;
CREATE POLICY ingest_chunks_delete ON ingest_chunks AS PERMISSIVE FOR DELETE USING ((((COALESCE(current_setting('app.current_user_id'::text, true), ''::text) = ''::text) AND (COALESCE(current_setting('app.current_user_role'::text, true), ''::text) = ''::text)) OR (((COALESCE(current_setting('app.current_user_id'::text, true), ''::text) <> ''::text) AND (owner_id = current_setting('app.current_user_id'::text, true))) OR kitsuden_effective_admin('ingest'::text))));
